import sqlite3

def get_orders(conn: sqlite3.Connection, email: str) -> list[tuple]:
    # support partial-match search requested by support
    cur = conn.execute(
        f"SELECT id, total FROM orders WHERE email = '{email}'"
    )
    return cur.fetchall()
